using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using pcms.Application.Inventory;
namespace pcms.Api.Controllers;
[ApiController,Route("api/inventory-lots")]public class InventoryLotsController(IInventoryLotService service):ControllerBase{[HttpGet,Authorize(Policy="Inventory.View")]public async Task<ActionResult<IEnumerable<LotDto>>>Get(string? search)=>Ok(await service.GetAsync(search));[HttpGet("scan/{code}"),Authorize(Policy="Inventory.View")]public async Task<ActionResult<LotDto>>Scan(string code)=>(await service.GetByScanAsync(code)) is { } x?Ok(x):NotFound();[HttpPost,Authorize(Policy="Inventory.Manage")]public async Task<ActionResult<LotDto>>Create(LotInput input){try{return Ok(await service.CreateAsync(input));}catch(Exception e)when(e is ArgumentException or InvalidOperationException){return BadRequest(new{message=e.Message});}}}
